import {createFlightSequence,FLIGHT_PHASES} from './flight-sequence.mjs';
export function mountFlightControls({host,box,ensureRacer,stopRacer}){
 const area=document.createElement('div');area.id='flight-crash';area.innerHTML=`<style>#fc-phases{display:flex;gap:5px;flex-wrap:wrap;padding:0;list-style:none}#fc-phases li{font-size:11px;padding:6px 8px;background:#17252c;border-radius:7px}#fc-phases li[aria-current="step"]{background:#7b5e37;color:white}#fc-data{white-space:pre-wrap;max-height:300px;overflow:auto}#fc-progress{width:100%;accent-color:#c4a36b}</style><h3>Flug + Crash</h3><div class="vr-row"><button class="btn primary" id="fc-demo">30-s-Flug + Crash</button><button class="btn" id="fc-stop">Flug / Crash stoppen</button><label>Crash-Material<select id="fc-material"><option value="wood">Holz</option><option value="stone">Stein</option><option value="crystal">Kristall</option></select></label><a id="fc-recording" hidden>Gemeinsame Hörprobe herunterladen</a></div><output id="fc-status" aria-live="polite">Gestoppt. Antrieb oben wählen; Racer-Auswahl startet die Probe als Jetpack.</output><progress id="fc-progress" value="0" max="30"></progress><ol id="fc-phases">${FLIGHT_PHASES.map(x=>'<li>'+x+'</li>').join('')}</ol><details id="fc-controls"><summary>Flug steuern &amp; Messungen</summary><p class="tiny">Manuell: oben Jetpack, Jet, Propeller, Turbine oder Antigrav wählen und Motor starten. Diese Studio-Abfolge ist keine Spielphysik; die spätere World sendet echte Bewegungs- und Kontaktfakten.</p><div class="vr-row"><label>Banking<input id="fc-bank" type="range" min="-1" max="1" step=".01" value="0"></label><label>Steigen / Sinken<input id="fc-vertical" type="range" min="-1" max="1" step=".01" value="0"></label><label>Luftbremse<input id="fc-airbrake" type="range" min="0" max="1" step=".01" value="0"></label><label><input id="fc-geared" type="checkbox"> Mit Getriebe · nur Hybrid-Racer</label><label><input id="fc-power" type="checkbox" checked> Antrieb an</label></div><p class="tiny">Zwei Explosionen sind bewusst inszenierte Treffer; Bruch und leise Trümmerkontakte folgen separat. Kontakt-Nachklänge sind Ausschnitte aus echten Materialaufnahmen, keine unabhängig aufgenommenen Einzeltreffer.</p><a href="./racer/FLIGHT_CONSUMER.md" target="_blank">Anschluss &amp; Grenzen</a><details><summary>Technische Messungen</summary><pre id="fc-data"></pre></details></details>`;
 const reference=box.querySelector('details');reference.before(area);
 const $=id=>area.querySelector('#'+id);let sequence,racer,combat,epoch=0,loading=false,lastPaint=-1,recording,capture,clipUrl;
 function finish(){if(recording?.state==='recording')recording.stop();if(capture){capture.output.disconnect(capture.node);capture=null;}}
 function cancel(){const shouldStop=loading||sequence?.snapshot().running;epoch++;loading=false;if(shouldStop){sequence?.stop();racer?.stop();combat?.stop();}finish();$('fc-status').textContent='Gestoppt · Flug und Kaskade beendet.';paint(true);}
 function record(){finish();if(!window.MediaRecorder)return;try{const g=host.audioContext,node=g.createMediaStreamDestination(),output=host.graphOutput();output.connect(node);capture={node,output};const parts=[],type=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t)),r=new MediaRecorder(node.stream,type?{mimeType:type}:{});recording=r;r.ondataavailable=e=>{if(e.data.size)parts.push(e.data)};r.onstop=()=>{if(clipUrl)URL.revokeObjectURL(clipUrl);clipUrl=URL.createObjectURL(new Blob(parts,{type:r.mimeType}));$('fc-recording').href=clipUrl;$('fc-recording').download='kfb-flight-crash-r1.'+(r.mimeType.includes('mp4')?'m4a':'webm');$('fc-recording').hidden=false;};r.start();}catch(e){$('fc-status').textContent='Probe läuft; Aufnahme nicht verfügbar: '+e.message;}}
 async function begin(){stopRacer();host.combat.stop();const token=++epoch;loading=true;$('fc-status').textContent='Private Antriebe und Materialklänge prüfen …';try{const r=await ensureRacer(),c=await host.combat.getConsumer();if(token!==epoch)return;racer=r;combat=c;await Promise.all([r.start(),c.start()]);if(token!==epoch)return;c.setContext({room:'outdoor',experimentalLayers:false});sequence=createFlightSequence({audioContext:host.audioContext,racer:r,combat:c});const profile=box.querySelector('#vr-mode').value;record();sequence.start({profile:['prop','jet','jetpack','turbine','antigrav'].includes(profile)?profile:'jetpack',material:$('fc-material').value});$('fc-status').textContent='Läuft · Start → Banking → Luftbremse → Einschlag → Kaskade.';paint(true);}catch(e){if(token!==epoch)return;cancel();$('fc-status').textContent='Nicht gestartet: '+e.message;}finally{if(token===epoch)loading=false;}}
 function paint(force=false){if(!sequence)return;const s=sequence.snapshot(),now=host.audioContext.currentTime;if(!force&&now-lastPaint<.1)return;lastPaint=now;$('fc-progress').value=s.elapsed;area.querySelectorAll('#fc-phases li').forEach((li,i)=>{if(FLIGHT_PHASES[i]===s.phase)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current');});$('fc-data').textContent=JSON.stringify({revision:'0.10.0',hostContexts:host.audioContextsCreated,...s,racer:racer?.snapshot(),combat:combat?.snapshot()},null,2);if(!s.running&&s.elapsed===30){finish();$('fc-status').textContent='Probe beendet · alle Flug-/Kaskadenquellen gestoppt.';}}
 function manual(){if(sequence?.snapshot().running)return;host.racer.setTelemetry({bank:Number($('fc-bank').value),vertical:Number($('fc-vertical').value),airbrake:Number($('fc-airbrake').value),geared:$('fc-geared').checked,engineOn:$('fc-power').checked});}
 for(const id of ['fc-bank','fc-vertical','fc-airbrake','fc-geared','fc-power'])$(id).oninput=manual;
 $('fc-demo').onclick=begin;$('fc-stop').onclick=stopRacer;host.racer.getFlightSnapshot=()=>sequence?.snapshot()||{running:false};host.racer.cancelFlight=()=>{if(loading||sequence?.snapshot().running)stopRacer();};
 if(location.hash==='#flight'){document.querySelector('#vr-shortcut').click();area.scrollIntoView({block:'start'});}
 return {cancel,applyManual:manual,tick(){sequence?.tick();paint();for(const id of ['fc-bank','fc-vertical','fc-airbrake','fc-geared','fc-power'])$(id).disabled=!!sequence?.snapshot().running;},get running(){return !!sequence?.snapshot().running}};
}
